import{_ as r,o as t,c as a,a2 as o}from"./chunks/framework.CdvW4CUT.js";const h=JSON.parse('{"title":"Kernel 日报 2026-10-27","description":"","frontmatter":{},"headers":[],"relativePath":"notes/kernel-digest/2026/10/27.md","filePath":"notes/kernel-digest/2026/10/27.md"}'),n={name:"notes/kernel-digest/2026/10/27.md"};function l(i,e,s,p,c,u){return t(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="kernel-日报-2026-10-27" tabindex="-1">Kernel 日报 2026-10-27 <a class="header-anchor" href="#kernel-日报-2026-10-27" aria-label="Permalink to &quot;Kernel 日报 2026-10-27&quot;">​</a></h1><blockquote><p>生成时间：2026-10-27T01:49:51Z｜共 42 条</p></blockquote><h2 id="今日-top-5" tabindex="-1">今日 Top 5 <a class="header-anchor" href="#今日-top-5" aria-label="Permalink to &quot;今日 Top 5&quot;">​</a></h2><h3 id="linux-7-4-preps-cxl-for-very-neat-dynamic-capacity-devices-dcd" tabindex="-1"><a href="https://www.phoronix.com/news/Linux-7.4-CXL" target="_blank" rel="noreferrer">Linux 7.4 Preps CXL For Very Neat Dynamic Capacity Devices &quot;DCD&quot;</a> <a class="header-anchor" href="#linux-7-4-preps-cxl-for-very-neat-dynamic-capacity-devices-dcd" aria-label="Permalink to &quot;[Linux 7.4 Preps CXL For Very Neat Dynamic Capacity Devices &quot;DCD&quot;](https://www.phoronix.com/news/Linux-7.4-CXL)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix｜其他动态</em></p><p>Linux 7.4 的 Compute Express Link（CXL）子系统改动已合并，本周期重点是为支持 Dynamic Capacity Devices（DCD）做准备。DCD 允许设备在运行时动态增减可用容量，是 CXL 内存扩展的重要特性。</p><blockquote><p><strong>学习价值</strong>：CXL 与动态容量是内存管理前沿方向，值得结合 mm 子系统的内存热插拔机制一起学习。</p></blockquote><h3 id="initial-support-for-the-apple-m4-apple-a18-pro-make-it-into-linux-7-4" tabindex="-1"><a href="https://www.phoronix.com/news/Linux-7.4-SoCs" target="_blank" rel="noreferrer">Initial Support For The Apple M4 &amp; Apple A18 Pro Make It Into Linux 7.4</a> <a class="header-anchor" href="#initial-support-for-the-apple-m4-apple-a18-pro-make-it-into-linux-7-4" aria-label="Permalink to &quot;[Initial Support For The Apple M4 &amp; Apple A18 Pro Make It Into Linux 7.4](https://www.phoronix.com/news/Linux-7.4-SoCs)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix｜其他动态</em></p><p>Linux 7.4 合并了大量 SoC 补丁，新增数十款开发板支持以及多个新 SoC，包括 Apple M4 与 MacBook Neo 所用的 Apple A18 Pro。Google Tensor 5 与 Pixel 10 系列设备也终于进入主线，此外还有尚未发布的 Qualcomm SoC 支持。</p><blockquote><p><strong>学习价值</strong>：展示了 ARM/SoC 平台支持进入 mainline 的典型路径，适合关注 Device Tree 与平台驱动的学习者。</p></blockquote><h3 id="ext4-lands-optional-buffered-iomap-for-significant-performance-win-with-large-writes" tabindex="-1"><a href="https://www.phoronix.com/news/Linux-7.4-EXT4" target="_blank" rel="noreferrer">EXT4 Lands Optional Buffered IOmap For Significant Performance Win With Large Writes</a> <a class="header-anchor" href="#ext4-lands-optional-buffered-iomap-for-significant-performance-win-with-large-writes" aria-label="Permalink to &quot;[EXT4 Lands Optional Buffered IOmap For Significant Performance Win With Large Writes](https://www.phoronix.com/news/Linux-7.4-EXT4)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix｜文件系统与存储</em></p><p>Linux 7.4 合并窗口合入 EXT4 文件系统改动，核心特性是可选启用 buffered IOmap，在大块写入场景可带来「显著」性能提升。该特性为 opt-in，需显式开启。</p><blockquote><p><strong>学习价值</strong>：适合研究 EXT4 写路径中 buffered IO 与 iomap 的衔接，以及新特性如何以 opt-in 方式渐进落地。</p></blockquote><h3 id="patch-mm-huge-memory-fix-deferred-split-list-corruption-on-partial-unmap" tabindex="-1"><a href="https://lore.kernel.org/all/20261026-thpsplit-careful-v1-1-d357d70fd6f4@columbia.edu/" target="_blank" rel="noreferrer">[PATCH] mm/huge_memory: fix deferred split list corruption on partial unmap</a> <a class="header-anchor" href="#patch-mm-huge-memory-fix-deferred-split-list-corruption-on-partial-unmap" aria-label="Permalink to &quot;[[PATCH] mm/huge_memory: fix deferred split list corruption on partial unmap](https://lore.kernel.org/all/20261026-thpsplit-careful-v1-1-d357d70fd6f4@columbia.edu/)&quot;">​</a></h3><p><em>Mani Tofigh via B4 Relay (<a href="mailto:devnull+mt4022.columbia.edu@kernel.org" target="_blank" rel="noreferrer">devnull+mt4022.columbia.edu@kernel.org</a>)｜linux-mm｜内存管理</em></p><p>补丁指出当 THP 在被 deferred split shrinker 扫描期间发生部分 unmap 时，deferred split list 可能被破坏，CONFIG_DEBUG_LIST 下后续释放 folio 会触发 list_del corruption 警告，调用栈涉及 __list_lru_del 与 __folio_unqueue_deferred_split。补丁针对该并发竞态修复链表一致性。</p><blockquote><p><strong>学习价值</strong>：是理解 THP deferred split、folio 队列与 shrinker 并发交互的优秀实例，适合精读 mm 补丁。</p></blockquote><h3 id="patch-iwl-net-e1000e-fix-tx-descriptor-field-wrapping" tabindex="-1"><a href="https://lore.kernel.org/all/20261027012958.52524-1-tactii@gmail.com/" target="_blank" rel="noreferrer">[PATCH iwl-net] e1000e: fix Tx descriptor field wrapping</a> <a class="header-anchor" href="#patch-iwl-net-e1000e-fix-tx-descriptor-field-wrapping" aria-label="Permalink to &quot;[[PATCH iwl-net] e1000e: fix Tx descriptor field wrapping](https://lore.kernel.org/all/20261027012958.52524-1-tactii@gmail.com/)&quot;">​</a></h3><p><em>Matt Vollrath (<a href="mailto:tactii@gmail.com" target="_blank" rel="noreferrer">tactii@gmail.com</a>)｜netdev｜网络</em></p><p>修复 e1000e 网卡驱动的 Tx 描述符字段回绕 bug：当 skb 头部长度超过 e1000_context_desc 中 tucss/tucso 的 u8 字段宽度时，回绕值被发送到网卡导致挂起，可用非特权 Python 脚本在 I218-V 上复现。修复方案是在头部长度或校验和偏移超限时禁用 GSO 和 checksum offload，并补偿软件插入的 VLAN tag。该 bug 自驱动引入以来一直存在，已 CC stable。</p><blockquote><p><strong>学习价值</strong>：展示了硬件描述符字段宽度限制引发的驱动级 bug 及其防御性处理方式，是学习网卡 offload 机制与驱动安全编码的好例子。</p></blockquote><h2 id="分类目录" tabindex="-1">分类目录 <a class="header-anchor" href="#分类目录" aria-label="Permalink to &quot;分类目录&quot;">​</a></h2><ul><li><strong>内存管理</strong>（4 条）</li><li><strong>网络</strong>（2 条）</li><li><strong>文件系统与存储</strong>（4 条）</li><li><strong>Rust in Linux</strong>（15 条）</li><li><strong>跟踪与性能</strong>（1 条）</li><li><strong>版本发布动态</strong>（3 条）</li><li><strong>其他动态</strong>（13 条）</li></ul><h2 id="内存管理" tabindex="-1">内存管理 <a class="header-anchor" href="#内存管理" aria-label="Permalink to &quot;内存管理&quot;">​</a></h2><h3 id="syzbot-jffs2-kasan-slab-use-after-free-read-in-jffs2-erase-pending-blocks-2" tabindex="-1"><a href="https://lore.kernel.org/all/6adfffa9.6200f071.51519.0f0e.GAE@google.com/" target="_blank" rel="noreferrer">[syzbot] [jffs2?] KASAN: slab-use-after-free Read in jffs2_erase_pending_blocks (2)</a> <a class="header-anchor" href="#syzbot-jffs2-kasan-slab-use-after-free-read-in-jffs2-erase-pending-blocks-2" aria-label="Permalink to &quot;[[syzbot] [jffs2?] KASAN: slab-use-after-free Read in jffs2_erase_pending_blocks (2)](https://lore.kernel.org/all/6adfffa9.6200f071.51519.0f0e.GAE@google.com/)&quot;">​</a></h3><p><em>syzbot (<a href="mailto:syzbot+49c659b5564b2a44083c@syzkaller.appspotmail.com" target="_blank" rel="noreferrer">syzbot+49c659b5564b2a44083c@syzkaller.appspotmail.com</a>)｜lkml</em></p><p>syzbot 报告 jffs2 中 jffs2_erase_pending_blocks 出现 KASAN slab-use-after-free 读，基于 upstream 的 net-next-7.4 合并提交。目前尚无 reproducer，报告附有 console 日志、内核配置与磁盘镜像等资产。</p><blockquote><p><strong>学习价值</strong>：可学习 syzbot 报告结构与 jffs2 擦除路径的生命周期管理问题，是典型的 UAF 调试素材。</p></blockquote><h3 id="patch-mm-huge-memory-fix-deferred-split-list-corruption-on-partial-unmap-1" tabindex="-1"><a href="https://lore.kernel.org/all/20261026-thpsplit-careful-v1-1-d357d70fd6f4@columbia.edu/" target="_blank" rel="noreferrer">[PATCH] mm/huge_memory: fix deferred split list corruption on partial unmap</a> <a class="header-anchor" href="#patch-mm-huge-memory-fix-deferred-split-list-corruption-on-partial-unmap-1" aria-label="Permalink to &quot;[[PATCH] mm/huge_memory: fix deferred split list corruption on partial unmap](https://lore.kernel.org/all/20261026-thpsplit-careful-v1-1-d357d70fd6f4@columbia.edu/)&quot;">​</a></h3><p><em>Mani Tofigh via B4 Relay (<a href="mailto:devnull+mt4022.columbia.edu@kernel.org" target="_blank" rel="noreferrer">devnull+mt4022.columbia.edu@kernel.org</a>)｜linux-mm</em></p><p>补丁指出当 THP 在被 deferred split shrinker 扫描期间发生部分 unmap 时，deferred split list 可能被破坏，CONFIG_DEBUG_LIST 下后续释放 folio 会触发 list_del corruption 警告，调用栈涉及 __list_lru_del 与 __folio_unqueue_deferred_split。补丁针对该并发竞态修复链表一致性。</p><blockquote><p><strong>学习价值</strong>：是理解 THP deferred split、folio 队列与 shrinker 并发交互的优秀实例，适合精读 mm 补丁。</p></blockquote><h3 id="patch-45-46-mm-memory-tiers-unregister-empty-tiers-outside-memory-tier-lock" tabindex="-1"><a href="https://lore.kernel.org/all/20261027-fixes_core-v1-45-6f74bec9a5bb@kernel.org/" target="_blank" rel="noreferrer">[PATCH 45/46] mm/memory-tiers: unregister empty tiers outside memory_tier_lock</a> <a class="header-anchor" href="#patch-45-46-mm-memory-tiers-unregister-empty-tiers-outside-memory-tier-lock" aria-label="Permalink to &quot;[[PATCH 45/46] mm/memory-tiers: unregister empty tiers outside memory_tier_lock](https://lore.kernel.org/all/20261027-fixes_core-v1-45-6f74bec9a5bb@kernel.org/)&quot;">​</a></h3><p><em>David Hildenbrand (Arm) (<a href="mailto:david@kernel.org" target="_blank" rel="noreferrer">david@kernel.org</a>)｜linux-mm</em></p><p>修复 mm/memory-tiers 中的死锁：节点下线清空其 memory tier 时，clear_node_memory_tier() 在持有 memory_tier_lock 的情况下调用 device_unregister()，而并发的 sysfs 读取（nodelist_show()）会阻塞在该 mutex 上，kernfs_drain() 等待读取完成，形成 ABBA 死锁。修复是让 clear_node_memory_tier() 返回原 tier 指针，由调用方在锁外执行 unlink 和 device_unregister()。</p><blockquote><p><strong>学习价值</strong>：典型的 &quot;在锁内调用 device_unregister() 导致死锁&quot; 案例，对学习锁粒度设计和 sysfs/kernfs 生命周期机制非常有价值。</p></blockquote><h3 id="patch-v2-2-2-virtio-balloon-submit-reported-pages-as-individual-buffers" tabindex="-1"><a href="https://lore.kernel.org/all/02257263433b001cd0a55a52486857df81dd4246.1793057483.git.mst@redhat.com/" target="_blank" rel="noreferrer">[PATCH v2 2/2] virtio_balloon: submit reported pages as individual buffers</a> <a class="header-anchor" href="#patch-v2-2-2-virtio-balloon-submit-reported-pages-as-individual-buffers" aria-label="Permalink to &quot;[[PATCH v2 2/2] virtio_balloon: submit reported pages as individual buffers](https://lore.kernel.org/all/02257263433b001cd0a55a52486857df81dd4246.1793057483.git.mst@redhat.com/)&quot;">​</a></h3><p><em>Michael S. Tsirkin (<a href="mailto:mst@redhat.com" target="_blank" rel="noreferrer">mst@redhat.com</a>)｜rust-for-linux</em></p><p>修复 virtio_balloon 的 virtio 规范违规：在 arm64 64KiB 页内核上，free page reporting 的 scatter-gather 列表可能形成超过 4 GiB 的 descriptor chain，违反 virtio 规范中单条 descriptor chain 不得超过 2^32 字节的要求，并会破坏 Rust-VMM。修复方案是将每个上报页作为单独的 virtqueue buffer 提交。</p><blockquote><p><strong>学习价值</strong>：展示了大页内核下 scatter-gather 聚合可能违反协议限制的隐蔽 bug，对学习 virtio 规范约束和 free page reporting 机制很有价值。</p></blockquote><h2 id="网络" tabindex="-1">网络 <a class="header-anchor" href="#网络" aria-label="Permalink to &quot;网络&quot;">​</a></h2><h3 id="patch-iwl-net-e1000e-fix-tx-descriptor-field-wrapping-1" tabindex="-1"><a href="https://lore.kernel.org/all/20261027012958.52524-1-tactii@gmail.com/" target="_blank" rel="noreferrer">[PATCH iwl-net] e1000e: fix Tx descriptor field wrapping</a> <a class="header-anchor" href="#patch-iwl-net-e1000e-fix-tx-descriptor-field-wrapping-1" aria-label="Permalink to &quot;[[PATCH iwl-net] e1000e: fix Tx descriptor field wrapping](https://lore.kernel.org/all/20261027012958.52524-1-tactii@gmail.com/)&quot;">​</a></h3><p><em>Matt Vollrath (<a href="mailto:tactii@gmail.com" target="_blank" rel="noreferrer">tactii@gmail.com</a>)｜netdev</em></p><p>修复 e1000e 网卡驱动的 Tx 描述符字段回绕 bug：当 skb 头部长度超过 e1000_context_desc 中 tucss/tucso 的 u8 字段宽度时，回绕值被发送到网卡导致挂起，可用非特权 Python 脚本在 I218-V 上复现。修复方案是在头部长度或校验和偏移超限时禁用 GSO 和 checksum offload，并补偿软件插入的 VLAN tag。该 bug 自驱动引入以来一直存在，已 CC stable。</p><blockquote><p><strong>学习价值</strong>：展示了硬件描述符字段宽度限制引发的驱动级 bug 及其防御性处理方式，是学习网卡 offload 机制与驱动安全编码的好例子。</p></blockquote><h3 id="patch-rfc-net-next-net-qrtr-wake-the-system-for-userspace-packets" tabindex="-1"><a href="https://lore.kernel.org/all/20261027-qrtr-wakeup-v1-1-42b0a5816ff9@gmail.com/" target="_blank" rel="noreferrer">[PATCH RFC net-next] net: qrtr: Wake the system for userspace packets</a> <a class="header-anchor" href="#patch-rfc-net-next-net-qrtr-wake-the-system-for-userspace-packets" aria-label="Permalink to &quot;[[PATCH RFC net-next] net: qrtr: Wake the system for userspace packets](https://lore.kernel.org/all/20261027-qrtr-wakeup-v1-1-42b0a5816ff9@gmail.com/)&quot;">​</a></h3><p><em>Filippo Falezza (<a href="mailto:effeffe99@gmail.com" target="_blank" rel="noreferrer">effeffe99@gmail.com</a>)｜netdev</em></p><p>QRTR 补丁（RFC）解决 Qualcomm 手机在 suspend-to-idle 期间来电/短信丢失的问题：GLINK 中断（IRQF_NO_SUSPEND）携带 QMI indication 到达并排入 QRTR socket，但无人上报 wakeup 事件，系统回到空闲后用户空间冻结导致来电无响应。由于不能为每个 GLINK 中断都上报 wakeup（会中断大多数挂起），该补丁让 QRTR 层针对用户空间包决定是否唤醒系统。</p><blockquote><p><strong>学习价值</strong>：深入展示了 Android/Qualcomm 平台上 suspend、wakeup source 与网络协议栈交互的复杂性，对学习电源管理与 QRTR/QMI 架构很有帮助。</p></blockquote><h2 id="文件系统与存储" tabindex="-1">文件系统与存储 <a class="header-anchor" href="#文件系统与存储" aria-label="Permalink to &quot;文件系统与存储&quot;">​</a></h2><h3 id="mesa-27-0-switching-to-kraid-compiler-by-default-for-arm-mali-gpus" tabindex="-1"><a href="https://www.phoronix.com/news/Mesa-27.0-Goes-Kraid" target="_blank" rel="noreferrer">Mesa 27.0 Switching To Kraid Compiler By Default For Arm Mali GPUs</a> <a class="header-anchor" href="#mesa-27-0-switching-to-kraid-compiler-by-default-for-arm-mali-gpus" aria-label="Permalink to &quot;[Mesa 27.0 Switching To Kraid Compiler By Default For Arm Mali GPUs](https://www.phoronix.com/news/Mesa-27.0-Goes-Kraid)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>Mesa 27.0 将默认启用 Kraid 这一面向较新 Arm Mali GPU 的现代图形编译器，取代原有编译器。Kraid 早在 2026 年 6 月已合入 Mesa 26.2，但当时并非默认；Mesa 27.0 计划于第一季度发布并切换默认。该改动主要影响 Mali GPU 上的 shader 编译路径与驱动栈。</p><blockquote><p><strong>学习价值</strong>：虽属用户态图形栈而非内核本体，但可借此理解 DRM/Mali 内核驱动与 Mesa 用户态编译器的分工边界。</p></blockquote><h3 id="moxnox-nt-like-posix-compatible-hobby-os-running-atop-btrfs" tabindex="-1"><a href="https://www.phoronix.com/news/Moxnox-OS" target="_blank" rel="noreferrer">Moxnox: NT-Like, POSIX-Compatible Hobby OS Running Atop Btrfs</a> <a class="header-anchor" href="#moxnox-nt-like-posix-compatible-hobby-os-running-atop-btrfs" aria-label="Permalink to &quot;[Moxnox: NT-Like, POSIX-Compatible Hobby OS Running Atop Btrfs](https://www.phoronix.com/news/Moxnox-OS)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>Moxnox 是由以 Windows Btrfs 驱动闻名的开发者 Mark Harmstone 花数年打造的业余操作系统，定位为类 NT、兼容 POSIX，并运行在 Btrfs 之上。它并非 Linux 内核项目，而是独立 OS 实验。</p><blockquote><p><strong>学习价值</strong>：可作为理解 Btrfs 磁盘格式与文件系统驱动实现（跨平台复用）的旁证案例，但与内核代码关联有限。</p></blockquote><h3 id="ext4-lands-optional-buffered-iomap-for-significant-performance-win-with-large-writes-1" tabindex="-1"><a href="https://www.phoronix.com/news/Linux-7.4-EXT4" target="_blank" rel="noreferrer">EXT4 Lands Optional Buffered IOmap For Significant Performance Win With Large Writes</a> <a class="header-anchor" href="#ext4-lands-optional-buffered-iomap-for-significant-performance-win-with-large-writes-1" aria-label="Permalink to &quot;[EXT4 Lands Optional Buffered IOmap For Significant Performance Win With Large Writes](https://www.phoronix.com/news/Linux-7.4-EXT4)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>Linux 7.4 合并窗口合入 EXT4 文件系统改动，核心特性是可选启用 buffered IOmap，在大块写入场景可带来「显著」性能提升。该特性为 opt-in，需显式开启。</p><blockquote><p><strong>学习价值</strong>：适合研究 EXT4 写路径中 buffered IO 与 iomap 的衔接，以及新特性如何以 opt-in 方式渐进落地。</p></blockquote><h3 id="patch-46-46-fs-proc-task-mmu-refuse-addresses-beyond-32-bits-on-32bit" tabindex="-1"><a href="https://lore.kernel.org/all/20261027-fixes_core-v1-46-6f74bec9a5bb@kernel.org/" target="_blank" rel="noreferrer">[PATCH 46/46] fs/proc/task_mmu: refuse addresses beyond 32 bits on 32bit</a> <a class="header-anchor" href="#patch-46-46-fs-proc-task-mmu-refuse-addresses-beyond-32-bits-on-32bit" aria-label="Permalink to &quot;[[PATCH 46/46] fs/proc/task_mmu: refuse addresses beyond 32 bits on 32bit](https://lore.kernel.org/all/20261027-fixes_core-v1-46-6f74bec9a5bb@kernel.org/)&quot;">​</a></h3><p><em>David Hildenbrand (Arm) (<a href="mailto:david@kernel.org" target="_blank" rel="noreferrer">david@kernel.org</a>)｜linux-mm</em></p><p>修复 fs/proc/task_mmu 中 PAGEMAP_SCAN 的参数校验问题：struct pm_scan_arg 中的地址为 64 位，但在 32 位内核上 pagemap_scan_get_args() 直接将其截断为 unsigned long，导致扫描 0x100001000-0x100002000 时实际操作了 0x1000-0x2000 并可能错误地执行 write-protect。修复方案是对超出地址空间的地址返回 -EFAULT。该补丁由 LLM 生成。</p><blockquote><p><strong>学习价值</strong>：展示了 32/64 位宽度截断这一经典内核 bug 模式，以及 PAGEMAP_SCAN 接口的参数校验细节，对理解用户态接口的健壮性很有参考价值。</p></blockquote><h2 id="rust-in-linux" tabindex="-1">Rust in Linux <a class="header-anchor" href="#rust-in-linux" aria-label="Permalink to &quot;Rust in Linux&quot;">​</a></h2><h3 id="systemd-adds-support-for-components-written-in-rust" tabindex="-1"><a href="https://lwn.net/Articles/1102970/" target="_blank" rel="noreferrer">Systemd adds support for components written in Rust</a> <a class="header-anchor" href="#systemd-adds-support-for-components-written-in-rust" aria-label="Permalink to &quot;[Systemd adds support for components written in Rust](https://lwn.net/Articles/1102970/)&quot;">​</a></h3><p><em>jzb｜lwn</em></p><p>Christian Brauner 宣布已合并「允许用 Rust 编写 systemd 叶子组件」的支持。Rust 仅用于新的叶子组件，现有代码不会被移植，其他组件所依赖的部分也不会用 Rust 实现。Brauner 表示项目希望在 systemd 核心中推进 Rust 支持，但 Rust 对动态库的支持仍存在若干阻碍，否则会导致每个二进制文件体积大幅膨胀；若进展顺利，该工作有望出现在 systemd v263 中。</p><blockquote><p><strong>学习价值</strong>：反映了 Rust 在系统级基础设施中落地的真实约束（动态库、二进制体积），与内核 Rust 支持的取舍高度相似。</p></blockquote><h3 id="patch-v3-0-3-rust-abstractions-for-the-spi-driver-subsystem" tabindex="-1"><a href="https://lore.kernel.org/all/tencent_1A6955961D79F8A63ADC6831840934770707@qq.com/" target="_blank" rel="noreferrer">[PATCH v3 0/3] Rust abstractions for the SPI driver subsystem</a> <a class="header-anchor" href="#patch-v3-0-3-rust-abstractions-for-the-spi-driver-subsystem" aria-label="Permalink to &quot;[[PATCH v3 0/3] Rust abstractions for the SPI driver subsystem](https://lore.kernel.org/all/tencent_1A6955961D79F8A63ADC6831840934770707@qq.com/)&quot;">​</a></h3><p><em>Shuai Liu (<a href="mailto:847807867@qq.com" target="_blank" rel="noreferrer">847807867@qq.com</a>)｜rust-for-linux</em></p><p>Rust SPI 驱动子系统抽象的 v3 系列封面：相比 v2，改用 info_unchecked_opt() 优雅处理无 driver_data 的 SPI id 表项；移除了不持 I/O 锁修改设备字段、可能与并发传输竞争的 SpiDevice::setup()；去掉了 write_then_read() 中的 bounce buffer，因为 C 核心的 spi_write_then_read() 已在内部复制到 DMA 安全的 bounce buffer。</p><blockquote><p><strong>学习价值</strong>：通过版本演进展示了 Rust 内核抽象设计中的并发安全与冗余拷贝消除考量，是学习 Rust driver abstraction 设计流程的优秀材料。</p></blockquote><h3 id="patch-v3-3-3-samples-rust-add-spi-driver-sample" tabindex="-1"><a href="https://lore.kernel.org/all/tencent_EC4E2C51F28E4D7CB8E76263133CEE93D208@qq.com/" target="_blank" rel="noreferrer">[PATCH v3 3/3] samples: rust: add SPI driver sample</a> <a class="header-anchor" href="#patch-v3-3-3-samples-rust-add-spi-driver-sample" aria-label="Permalink to &quot;[[PATCH v3 3/3] samples: rust: add SPI driver sample](https://lore.kernel.org/all/tencent_EC4E2C51F28E4D7CB8E76263133CEE93D208@qq.com/)&quot;">​</a></h3><p><em>Shuai Liu (<a href="mailto:847807867@qq.com" target="_blank" rel="noreferrer">847807867@qq.com</a>)｜rust-for-linux</em></p><p>为 Rust SPI 抽象添加示例驱动 samples/rust/rust_driver_spi.rs（66 行），演示如何使用这些抽象编写 SPI 驱动，并配套添加了 SAMPLE_RUST_DRIVER_SPI 的 Kconfig 选项和 Makefile 条目。</p><blockquote><p><strong>学习价值</strong>：一个简短完整的 Rust SPI 驱动样例，是初学者上手 Rust 内核驱动开发的理想起点。</p></blockquote><h3 id="patch-v3-2-3-rust-spi-add-spi-driver-abstractions" tabindex="-1"><a href="https://lore.kernel.org/all/tencent_93AC18D8C4933B9B7416CBA2FC7CD30DEE06@qq.com/" target="_blank" rel="noreferrer">[PATCH v3 2/3] rust: spi: add SPI driver abstractions</a> <a class="header-anchor" href="#patch-v3-2-3-rust-spi-add-spi-driver-abstractions" aria-label="Permalink to &quot;[[PATCH v3 2/3] rust: spi: add SPI driver abstractions](https://lore.kernel.org/all/tencent_93AC18D8C4933B9B7416CBA2FC7CD30DEE06@qq.com/)&quot;">​</a></h3><p><em>Shuai Liu (<a href="mailto:847807867@qq.com" target="_blank" rel="noreferrer">847807867@qq.com</a>)｜rust-for-linux</em></p><p>Rust SPI 驱动抽象的核心实现，包括 spi::DeviceId（驱动侧设备 id）、spi::Adapter（驱动注册，实现 driver::DriverLayout 和 driver::RegistrationOps）、spi::Driver trait（含 probe()/shutdown()/unbind() 回调）、spi::SpiDevice（封装 struct spi_device，提供配置访问器和 write()/read()/write_then_read() 操作）以及 module_spi_driver! 宏。</p><blockquote><p><strong>学习价值</strong>：展示了现代 Rust 内核驱动抽象的分层结构（DeviceId/Adapter/Driver/SpiDevice），是理解 Rust 驱动框架设计模式的范本。</p></blockquote><h3 id="patch-v3-1-3-rust-helpers-add-spi-helpers" tabindex="-1"><a href="https://lore.kernel.org/all/tencent_E4B7D8D204A1BBBF34374B9ABC53D313AE06@qq.com/" target="_blank" rel="noreferrer">[PATCH v3 1/3] rust: helpers: add SPI helpers</a> <a class="header-anchor" href="#patch-v3-1-3-rust-helpers-add-spi-helpers" aria-label="Permalink to &quot;[[PATCH v3 1/3] rust: helpers: add SPI helpers](https://lore.kernel.org/all/tencent_E4B7D8D204A1BBBF34374B9ABC53D313AE06@qq.com/)&quot;">​</a></h3><p><em>Shuai Liu (<a href="mailto:847807867@qq.com" target="_blank" rel="noreferrer">847807867@qq.com</a>)｜rust-for-linux</em></p><p>为 Rust 侧无法直接访问的 static inline C 函数（spi_unregister_driver()、spi_write()、spi_read()）添加 C helper 封装，并用 CONFIG_SPI 守护以避免 SPI 禁用时链接失败；同时在 bindgen 的 bindings_helper.h 中引入 &lt;linux/spi/spi.h&gt; 使 Rust 侧能访问 SPI 数据类型。</p><blockquote><p><strong>学习价值</strong>：清晰演示了 Rust/C 互操作中 static inline 函数需要 helper 封装这一常见模式，是学习 rust/bindings 与 rust/helpers 机制的基础知识。</p></blockquote><h3 id="patch-v5-10-11-drm-tyr-gem-flush-write-combine-bos-from-probe-time-coherence" tabindex="-1"><a href="https://lore.kernel.org/all/20261027-tyr-ioctls-v5-10-59dfe98cb003@kylinos.cn/" target="_blank" rel="noreferrer">[PATCH v5 10/11] drm/tyr: gem: flush write-combine BOs from probe-time coherence</a> <a class="header-anchor" href="#patch-v5-10-11-drm-tyr-gem-flush-write-combine-bos-from-probe-time-coherence" aria-label="Permalink to &quot;[[PATCH v5 10/11] drm/tyr: gem: flush write-combine BOs from probe-time coherence](https://lore.kernel.org/all/20261027-tyr-ioctls-v5-10-59dfe98cb003@kylinos.cn/)&quot;">​</a></h3><p><em>Ke Sun via B4 Relay (<a href="mailto:devnull+sunke.kylinos.cn@kernel.org" target="_blank" rel="noreferrer">devnull+sunke.kylinos.cn@kernel.org</a>)｜rust-for-linux</em></p><p>drm/tyr（Rust 编写的 DRM 驱动）修复非一致性设备上的缓存一致性问题：shmem 层通过 cached mapping 零初始化新页，而 tyr 以 write-combine 映射 buffer，在非一致设备上陈旧 cache line 可能覆盖后续 uncached 写入，导致 GPU 或用户空间读到零。修复是在 probe 时读取设备一致性，一致时用 write-back 映射，否则 write-combine，并在 BO_CREATE 时获取 sgtable 使 dma_map_sgtable() 在 uncached 访问前 flush 零初始化页。</p><blockquote><p><strong>学习价值</strong>：深入讲解 DMA 缓存一致性、write-combine 映射与 shmem 零初始化交互的陷阱，是学习非一致 SoC 上 GPU 驱动缓存管理的高级案例。</p></blockquote><h3 id="patch-v5-07-11-drm-tyr-add-vm-related-ioctls" tabindex="-1"><a href="https://lore.kernel.org/all/20261027-tyr-ioctls-v5-7-59dfe98cb003@kylinos.cn/" target="_blank" rel="noreferrer">[PATCH v5 07/11] drm/tyr: add VM-related ioctls</a> <a class="header-anchor" href="#patch-v5-07-11-drm-tyr-add-vm-related-ioctls" aria-label="Permalink to &quot;[[PATCH v5 07/11] drm/tyr: add VM-related ioctls](https://lore.kernel.org/all/20261027-tyr-ioctls-v5-7-59dfe98cb003@kylinos.cn/)&quot;">​</a></h3><p><em>Ke Sun via B4 Relay (<a href="mailto:devnull+sunke.kylinos.cn@kernel.org" target="_blank" rel="noreferrer">devnull+sunke.kylinos.cn@kernel.org</a>)｜rust-for-linux</em></p><p>为 Rust 编写的 drm/tyr 驱动实现 VM_CREATE、VM_DESTROY、VM_BIND 和 VM_GET_STATE 四个 ioctl。VM_CREATE 将新 VM 交给 per-file pool 管理，插入失败时由调用方销毁，避免泄漏；VM_DESTROY 即使有 in-flight job 持有引用也会移除并杀死 VM（与 panthor 行为一致）；VM_BIND 目前为同步执行。</p><blockquote><p><strong>学习价值</strong>：展示了 Rust DRM 驱动中如何设计资源生命周期与错误回滚路径，是学习 Rust 抽象下资源管理的好例子。</p></blockquote><h3 id="patch-v5-08-11-drm-tyr-add-bo-related-ioctls" tabindex="-1"><a href="https://lore.kernel.org/all/20261027-tyr-ioctls-v5-8-59dfe98cb003@kylinos.cn/" target="_blank" rel="noreferrer">[PATCH v5 08/11] drm/tyr: add BO-related ioctls</a> <a class="header-anchor" href="#patch-v5-08-11-drm-tyr-add-bo-related-ioctls" aria-label="Permalink to &quot;[[PATCH v5 08/11] drm/tyr: add BO-related ioctls](https://lore.kernel.org/all/20261027-tyr-ioctls-v5-8-59dfe98cb003@kylinos.cn/)&quot;">​</a></h3><p><em>Ke Sun via B4 Relay (<a href="mailto:devnull+sunke.kylinos.cn@kernel.org" target="_blank" rel="noreferrer">devnull+sunke.kylinos.cn@kernel.org</a>)｜rust-for-linux</em></p><p>为 drm/tyr 驱动实现 BO_CREATE 和 BO_MMAP_OFFSET ioctl，使用户态可以分配 GPU buffer 并获得 DRM mmap offset 以走通用 mmap 路径。BO_CREATE 会将请求大小按页对齐；BO_MMAP_OFFSET 拒绝 NO_MMAP 对象，因其不允许被 CPU 映射。</p><blockquote><p><strong>学习价值</strong>：可了解 GEM buffer 对象的创建与 mmap offset 分配流程，是理解 DRM 内存管理用户态接口的实用参考。</p></blockquote><h3 id="patch-v5-11-11-drm-tyr-gem-map-cached-bos-for-drm-panthor-bo-wb-mmap" tabindex="-1"><a href="https://lore.kernel.org/all/20261027-tyr-ioctls-v5-11-59dfe98cb003@kylinos.cn/" target="_blank" rel="noreferrer">[PATCH v5 11/11] drm/tyr: gem: map cached BOs for DRM_PANTHOR_BO_WB_MMAP</a> <a class="header-anchor" href="#patch-v5-11-11-drm-tyr-gem-map-cached-bos-for-drm-panthor-bo-wb-mmap" aria-label="Permalink to &quot;[[PATCH v5 11/11] drm/tyr: gem: map cached BOs for DRM_PANTHOR_BO_WB_MMAP](https://lore.kernel.org/all/20261027-tyr-ioctls-v5-11-59dfe98cb003@kylinos.cn/)&quot;">​</a></h3><p><em>Ke Sun via B4 Relay (<a href="mailto:devnull+sunke.kylinos.cn@kernel.org" target="_blank" rel="noreferrer">devnull+sunke.kylinos.cn@kernel.org</a>)｜rust-for-linux</em></p><p>在 bo_create 中接受 DRM_PANTHOR_BO_WB_MMAP 标志，允许用户态为频繁访问的 buffer 请求 cacheable 的 CPU 映射；coherent 设备本就映射为 cached。NO_MMAP 与 WB_MMAP 同时指定会返回 EINVAL；非 coherent 平台上由用户态负责 GPU 访问前后的 CPU cache 维护。</p><blockquote><p><strong>学习价值</strong>：深入讲解 GPU buffer 的 CPU cache 一致性问题与 WB_MMAP 语义，对理解 DMA coherence 与 cache maintenance 很有价值。</p></blockquote><h3 id="patch-v5-09-11-rust-device-expose-the-device-dma-attribute" tabindex="-1"><a href="https://lore.kernel.org/all/20261027-tyr-ioctls-v5-9-59dfe98cb003@kylinos.cn/" target="_blank" rel="noreferrer">[PATCH v5 09/11] rust: device: expose the device DMA attribute</a> <a class="header-anchor" href="#patch-v5-09-11-rust-device-expose-the-device-dma-attribute" aria-label="Permalink to &quot;[[PATCH v5 09/11] rust: device: expose the device DMA attribute](https://lore.kernel.org/all/20261027-tyr-ioctls-v5-9-59dfe98cb003@kylinos.cn/)&quot;">​</a></h3><p><em>Ke Sun via B4 Relay (<a href="mailto:devnull+sunke.kylinos.cn@kernel.org" target="_blank" rel="noreferrer">devnull+sunke.kylinos.cn@kernel.org</a>)｜rust-for-linux</em></p><p>为 rust/kernel 新增 DmaAttr 透明包装器，封装 device_get_dma_attr()，覆盖 unset、non-coherent、coherent 三种取值，并提供 is_coherent() 布尔访问器，使驱动能查询设备的 DMA coherence 属性。</p><blockquote><p><strong>学习价值</strong>：示范了如何用 Rust 透明包装器（transparent wrapper）为 C 函数建模三态返回值，是内核 Rust 抽象设计的典型模式。</p></blockquote><h3 id="patch-v5-05-11-drm-tyr-add-user-and-mcu-vm-specifications" tabindex="-1"><a href="https://lore.kernel.org/all/20261027-tyr-ioctls-v5-5-59dfe98cb003@kylinos.cn/" target="_blank" rel="noreferrer">[PATCH v5 05/11] drm/tyr: add user and MCU VM specifications</a> <a class="header-anchor" href="#patch-v5-05-11-drm-tyr-add-user-and-mcu-vm-specifications" aria-label="Permalink to &quot;[[PATCH v5 05/11] drm/tyr: add user and MCU VM specifications](https://lore.kernel.org/all/20261027-tyr-ioctls-v5-5-59dfe98cb003@kylinos.cn/)&quot;">​</a></h3><p><em>Ke Sun via B4 Relay (<a href="mailto:devnull+sunke.kylinos.cn@kernel.org" target="_blank" rel="noreferrer">devnull+sunke.kylinos.cn@kernel.org</a>)｜rust-for-linux</em></p><p>为 drm/tyr 的 MCU 和 user VM 提供不同 VA 布局的构造函数：new_for_fw() 构建仅内核可用的 4G 布局，new_for_user() 按 task_size 或用户指定大小划分地址空间，超限请求直接拒绝而非截断。用户范围通过 VM_CREATE 的 user_va_range 返回。</p><blockquote><p><strong>学习价值</strong>：展示了 GPU 虚拟地址空间布局设计及固件 VM 与用户 VM 的区分，对理解 GPU SVM/VA 管理有帮助。</p></blockquote><h3 id="patch-v5-00-11-drm-tyr-add-vm-and-bo-ioctl-support" tabindex="-1"><a href="https://lore.kernel.org/all/20261027-tyr-ioctls-v5-0-59dfe98cb003@kylinos.cn/" target="_blank" rel="noreferrer">[PATCH v5 00/11] drm/tyr: add VM and BO ioctl support</a> <a class="header-anchor" href="#patch-v5-00-11-drm-tyr-add-vm-and-bo-ioctl-support" aria-label="Permalink to &quot;[[PATCH v5 00/11] drm/tyr: add VM and BO ioctl support](https://lore.kernel.org/all/20261027-tyr-ioctls-v5-0-59dfe98cb003@kylinos.cn/)&quot;">​</a></h3><p><em>Ke Sun via B4 Relay (<a href="mailto:devnull+sunke.kylinos.cn@kernel.org" target="_blank" rel="noreferrer">devnull+sunke.kylinos.cn@kernel.org</a>)｜rust-for-linux</em></p><p>本系列为 Rust 编写的 drm/tyr 驱动添加 VM 和 BO ioctl，使其用户态接口与 panthor 对齐。基于 Danilo 的 drm-file 系列并携带 Sami Tolvanen 的 buffer cache 管理补丁，panthor IGT 测试已在 RK3588S 设备上通过。</p><blockquote><p><strong>学习价值</strong>：作为系列封面信，可了解 Rust GPU 驱动的整体开发流程、依赖关系与测试验证方式。</p></blockquote><h3 id="patch-v5-06-11-drm-tyr-add-bo-creation-and-lookup-helpers" tabindex="-1"><a href="https://lore.kernel.org/all/20261027-tyr-ioctls-v5-6-59dfe98cb003@kylinos.cn/" target="_blank" rel="noreferrer">[PATCH v5 06/11] drm/tyr: add BO creation and lookup helpers</a> <a class="header-anchor" href="#patch-v5-06-11-drm-tyr-add-bo-creation-and-lookup-helpers" aria-label="Permalink to &quot;[[PATCH v5 06/11] drm/tyr: add BO creation and lookup helpers](https://lore.kernel.org/all/20261027-tyr-ioctls-v5-6-59dfe98cb003@kylinos.cn/)&quot;">​</a></h3><p><em>Ke Sun via B4 Relay (<a href="mailto:devnull+sunke.kylinos.cn@kernel.org" target="_blank" rel="noreferrer">devnull+sunke.kylinos.cn@kernel.org</a>)｜rust-for-linux</em></p><p>为 drm/tyr 添加 BO ioctl 的辅助函数：new_object() 创建大小向上对齐到 PAGE_SIZE 的 GEM 对象，lookup_handle() 为 DRM file 解析 handle。</p><blockquote><p><strong>学习价值</strong>：展示了 GEM 对象创建与 handle 查找的基础封装，适合初学者理解 DRM GEM 子系统的基本操作。</p></blockquote><h3 id="patch-v5-03-11-rust-sync-arc-relax-foreignownable-for-arc" tabindex="-1"><a href="https://lore.kernel.org/all/20261027-tyr-ioctls-v5-3-59dfe98cb003@kylinos.cn/" target="_blank" rel="noreferrer">[PATCH v5 03/11] rust: sync: arc: relax <code>ForeignOwnable</code> for <code>Arc</code></a> <a class="header-anchor" href="#patch-v5-03-11-rust-sync-arc-relax-foreignownable-for-arc" aria-label="Permalink to &quot;[[PATCH v5 03/11] rust: sync: arc: relax `ForeignOwnable` for `Arc`](https://lore.kernel.org/all/20261027-tyr-ioctls-v5-3-59dfe98cb003@kylinos.cn/)&quot;">​</a></h3><p><em>Ke Sun via B4 Relay (<a href="mailto:devnull+sunke.kylinos.cn@kernel.org" target="_blank" rel="noreferrer">devnull+sunke.kylinos.cn@kernel.org</a>)｜rust-for-linux</em></p><p>修改 rust/kernel/sync/arc.rs 中的 ForeignOwnable 实现，去掉 &#39;static 约束，使借用驱动注册作用域的引用计数对象可以被 XArray 抽象以 foreign-owned 方式持有。</p><blockquote><p><strong>学习价值</strong>：深入 Rust 内核抽象中生命周期与 ForeignOwnable trait 的权衡，对理解 Rust 引用计数与 C 数据结构交互很有启发。</p></blockquote><h3 id="patch-v5-02-11-rust-task-add-task-size" tabindex="-1"><a href="https://lore.kernel.org/all/20261027-tyr-ioctls-v5-2-59dfe98cb003@kylinos.cn/" target="_blank" rel="noreferrer">[PATCH v5 02/11] rust: task: add task_size()</a> <a class="header-anchor" href="#patch-v5-02-11-rust-task-add-task-size" aria-label="Permalink to &quot;[[PATCH v5 02/11] rust: task: add task_size()](https://lore.kernel.org/all/20261027-tyr-ioctls-v5-2-59dfe98cb003@kylinos.cn/)&quot;">​</a></h3><p><em>Ke Sun via B4 Relay (<a href="mailto:devnull+sunke.kylinos.cn@kernel.org" target="_blank" rel="noreferrer">devnull+sunke.kylinos.cn@kernel.org</a>)｜rust-for-linux</em></p><p>新增 CurrentTask::task_size() 辅助方法，封装 TASK_SIZE_OF() 宏，供需要让用户态自选 GPU 虚拟地址的 DRM 驱动获取当前任务的地址空间大小，从而提供 CPU 可映射到相同地址的 GPU 范围。因 TASK_SIZE_OF() 在未定义的架构上回退到描述当前任务的 TASK_SIZE，故绑定到 current task。</p><blockquote><p><strong>学习价值</strong>：展示了如何为 C 宏添加 Rust 绑定时处理架构差异的细节，是内核 Rust 绑定工程的实用案例。</p></blockquote><h2 id="跟踪与性能" tabindex="-1">跟踪与性能 <a class="header-anchor" href="#跟踪与性能" aria-label="Permalink to &quot;跟踪与性能&quot;">​</a></h2><h3 id="snapdragon-x1-elite-acer-swift-14-ai-performance-on-the-ubuntu-26-10-x1e-concept" tabindex="-1"><a href="https://www.phoronix.com/review/ubuntu-2610-snapdragon-x1e" target="_blank" rel="noreferrer">Snapdragon X1 Elite / Acer Swift 14 AI Performance On The Ubuntu 26.10 X1E Concept</a> <a class="header-anchor" href="#snapdragon-x1-elite-acer-swift-14-ai-performance-on-the-ubuntu-26-10-x1e-concept" aria-label="Permalink to &quot;[Snapdragon X1 Elite / Acer Swift 14 AI Performance On The Ubuntu 26.10 X1E Concept](https://www.phoronix.com/review/ubuntu-2610-snapdragon-x1e)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>文章在 Ubuntu 26.10 Concept X1E ISO 上对 Snapdragon X1 Elite（Acer Swift 14 AI）进行性能基准测试，并与同一硬件上的 Ubuntu 26.04 LTS X1E 状态对比。内容属于 ARM 笔记本平台在 Linux 上的实际性能表现评测。</p><blockquote><p><strong>学习价值</strong>：可作为观察 ARM64 平台内核支持成熟度（电源管理、调度、驱动）对实际性能影响的参考数据。</p></blockquote><h2 id="版本发布动态" tabindex="-1">版本发布动态 <a class="header-anchor" href="#版本发布动态" aria-label="Permalink to &quot;版本发布动态&quot;">​</a></h2><h3 id="_7-2-13-stable" tabindex="-1"><a href="https://www.kernel.org/#kernel.org-stable-7.2.13-2026-10-26" target="_blank" rel="noreferrer">7.2.13: stable</a> <a class="header-anchor" href="#_7-2-13-stable" aria-label="Permalink to &quot;[7.2.13: stable](https://www.kernel.org/#kernel.org-stable-7.2.13-2026-10-26)&quot;">​</a></h3><p><em>kernel.org</em></p><p>kernel.org 发布 7.2.13 稳定版，发布日期为 2026-10-26，提供 tar.xz 源码包、PGP 签名、完整及增量补丁和 ChangeLog。</p><blockquote><p><strong>学习价值</strong>：稳定版发布信息，可用于跟踪内核版本演进，学习价值有限。</p></blockquote><h3 id="_6-18-59-longterm" tabindex="-1"><a href="https://www.kernel.org/#kernel.org-longterm-6.18.59-2026-10-26" target="_blank" rel="noreferrer">6.18.59: longterm</a> <a class="header-anchor" href="#_6-18-59-longterm" aria-label="Permalink to &quot;[6.18.59: longterm](https://www.kernel.org/#kernel.org-longterm-6.18.59-2026-10-26)&quot;">​</a></h3><p><em>kernel.org</em></p><p>kernel.org 发布 Linux 6.18.59 longterm（长期维护）版本，提供完整的源码包、PGP 签名、full/incremental patch 及 ChangeLog。这是 6.18 系列的稳定维护更新。</p><blockquote><p><strong>学习价值</strong>：了解 longterm 版本的发布流程与获取方式，是跟踪内核稳定分支维护节奏的基础。</p></blockquote><h3 id="next-20261026-linux-next" tabindex="-1"><a href="https://www.kernel.org/#kernel.org-linux-next-next-20261026-2026-10-26" target="_blank" rel="noreferrer">next-20261026: linux-next</a> <a class="header-anchor" href="#next-20261026-linux-next" aria-label="Permalink to &quot;[next-20261026: linux-next](https://www.kernel.org/#kernel.org-linux-next-next-20261026-2026-10-26)&quot;">​</a></h3><p><em>kernel.org</em></p><p>kernel.org 发布 linux-next 集成树快照 next-20261026。linux-next 汇聚各子系统树的待合并补丁，是下一个合并窗口内容的预演。</p><blockquote><p><strong>学习价值</strong>：关注 linux-next 快照有助于学习者提前观察即将进入 mainline 的新特性与子系统动态。</p></blockquote><h2 id="其他动态" tabindex="-1">其他动态 <a class="header-anchor" href="#其他动态" aria-label="Permalink to &quot;其他动态&quot;">​</a></h2><h3 id="python-s-experimental-jit-to-be-removed" tabindex="-1"><a href="https://lwn.net/Articles/1102102/" target="_blank" rel="noreferrer">[$] Python&#39;s experimental JIT to be removed</a> <a class="header-anchor" href="#python-s-experimental-jit-to-be-removed" aria-label="Permalink to &quot;[[$] Python&#39;s experimental JIT to be removed](https://lwn.net/Articles/1102102/)&quot;">​</a></h3><p><em>jzb｜lwn｜<strong>LWN 订阅文章，仅预览</strong></em></p><p>CPython 在 2024 年为 3.13 引入的实验性 JIT 编译器即将被移除。Python steering council 于 6 月宣布暂停 main 分支上的 JIT 工作，直到有被接受的 PEP 能解决维护性、兼容性问题，并给出明确的成功指标与完成时间表。维护者随后提出 PEP 836（&quot;JIT Go Brrr&quot;）试图满足要求，但经过数月讨论后 JIT 维护者仍决定放弃。</p><blockquote><p><strong>学习价值</strong>：虽非内核内容，但它展示了大型开源项目如何用 PEP 流程评估实验性优化特性的维护成本，对理解内核特性合入与淘汰机制有类比价值。</p></blockquote><h3 id="two-stable-kernels-for-monday" tabindex="-1"><a href="https://lwn.net/Articles/1102973/" target="_blank" rel="noreferrer">Two stable kernels for Monday</a> <a class="header-anchor" href="#two-stable-kernels-for-monday" aria-label="Permalink to &quot;[Two stable kernels for Monday](https://lwn.net/Articles/1102973/)&quot;">​</a></h3><p><em>jzb｜lwn</em></p><p>Greg Kroah-Hartman 发布了 7.2.13 与 6.18.59 两个 stable 内核版本。两个版本都包含遍布内核各处的修复，官方建议用户升级。</p><blockquote><p><strong>学习价值</strong>：可用于观察 stable 分支的维护节奏与版本号规则，是跟踪内核稳定版发布的好入口。</p></blockquote><h3 id="security-updates-for-monday" tabindex="-1"><a href="https://lwn.net/Articles/1102946/" target="_blank" rel="noreferrer">Security updates for Monday</a> <a class="header-anchor" href="#security-updates-for-monday" aria-label="Permalink to &quot;[Security updates for Monday](https://lwn.net/Articles/1102946/)&quot;">​</a></h3><p><em>jzb｜lwn</em></p><p>本周一发布了大量安全更新，涉及 AlmaLinux 与 Debian 等发行版。AlmaLinux 更新覆盖 ca-certificates、expat、kernel、openssl、nodejs、php、podman、postgresql 等众多包；Debian 则更新了 brotli、caddy、imagemagick、openjdk-17、openssl、thunderbird 等。</p><blockquote><p><strong>学习价值</strong>：可作为了解发行版安全响应流程与常见漏洞包范围的参考清单。</p></blockquote><h3 id="initial-support-for-the-apple-m4-apple-a18-pro-make-it-into-linux-7-4-1" tabindex="-1"><a href="https://www.phoronix.com/news/Linux-7.4-SoCs" target="_blank" rel="noreferrer">Initial Support For The Apple M4 &amp; Apple A18 Pro Make It Into Linux 7.4</a> <a class="header-anchor" href="#initial-support-for-the-apple-m4-apple-a18-pro-make-it-into-linux-7-4-1" aria-label="Permalink to &quot;[Initial Support For The Apple M4 &amp; Apple A18 Pro Make It Into Linux 7.4](https://www.phoronix.com/news/Linux-7.4-SoCs)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>Linux 7.4 合并了大量 SoC 补丁，新增数十款开发板支持以及多个新 SoC，包括 Apple M4 与 MacBook Neo 所用的 Apple A18 Pro。Google Tensor 5 与 Pixel 10 系列设备也终于进入主线，此外还有尚未发布的 Qualcomm SoC 支持。</p><blockquote><p><strong>学习价值</strong>：展示了 ARM/SoC 平台支持进入 mainline 的典型路径，适合关注 Device Tree 与平台驱动的学习者。</p></blockquote><h3 id="steam-frame-vr-headset-sees-mainline-support-with-linux-7-4" tabindex="-1"><a href="https://www.phoronix.com/news/Steam-Frame-FR-Linux-7.4" target="_blank" rel="noreferrer">Steam Frame VR Headset Sees Mainline Support With Linux 7.4</a> <a class="header-anchor" href="#steam-frame-vr-headset-sees-mainline-support-with-linux-7-4" aria-label="Permalink to &quot;[Steam Frame VR Headset Sees Mainline Support With Linux 7.4](https://www.phoronix.com/news/Steam-Frame-FR-Linux-7.4)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>Linux 7.4 主线内核将能够在 Steam Frame VR 头显上运行，相关硬件支持已合入。</p><blockquote><p><strong>学习价值</strong>：说明新硬件设备如何通过主线内核获得可用性，是观察设备支持上游化流程的实例。</p></blockquote><h3 id="linux-7-4-preps-cxl-for-very-neat-dynamic-capacity-devices-dcd-1" tabindex="-1"><a href="https://www.phoronix.com/news/Linux-7.4-CXL" target="_blank" rel="noreferrer">Linux 7.4 Preps CXL For Very Neat Dynamic Capacity Devices &quot;DCD&quot;</a> <a class="header-anchor" href="#linux-7-4-preps-cxl-for-very-neat-dynamic-capacity-devices-dcd-1" aria-label="Permalink to &quot;[Linux 7.4 Preps CXL For Very Neat Dynamic Capacity Devices &quot;DCD&quot;](https://www.phoronix.com/news/Linux-7.4-CXL)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>Linux 7.4 的 Compute Express Link（CXL）子系统改动已合并，本周期重点是为支持 Dynamic Capacity Devices（DCD）做准备。DCD 允许设备在运行时动态增减可用容量，是 CXL 内存扩展的重要特性。</p><blockquote><p><strong>学习价值</strong>：CXL 与动态容量是内存管理前沿方向，值得结合 mm 子系统的内存热插拔机制一起学习。</p></blockquote><h3 id="kmscon-10-1-released-with-support-for-per-monitor-configurations" tabindex="-1"><a href="https://www.phoronix.com/news/KMSCON-10.1-Released" target="_blank" rel="noreferrer">KMSCON 10.1 Released With Support For Per-Monitor Configurations</a> <a class="header-anchor" href="#kmscon-10-1-released-with-support-for-per-monitor-configurations" aria-label="Permalink to &quot;[KMSCON 10.1 Released With Support For Per-Monitor Configurations](https://www.phoronix.com/news/KMSCON-10.1-Released)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>面向 Linux DRM/KMS 接口的用户态终端模拟器 KMSCON 发布 10.1，作为内核内 VT 的替代方案。新版本支持在多显示器环境下对每台显示器单独配置，并包含其他多项改进。</p><blockquote><p><strong>学习价值</strong>：有助于理解内核 VT 与用户态 DRM/KMS 终端方案的差异，是研究控制台与显示栈的补充材料。</p></blockquote><h3 id="intel-ipu8-support-upstreamed-in-linux-7-4-for-nova-lake-laptops" tabindex="-1"><a href="https://www.phoronix.com/news/Linux-7.4-Media" target="_blank" rel="noreferrer">Intel IPU8 Support Upstreamed In Linux 7.4 For Nova Lake Laptops</a> <a class="header-anchor" href="#intel-ipu8-support-upstreamed-in-linux-7-4-for-nova-lake-laptops" aria-label="Permalink to &quot;[Intel IPU8 Support Upstreamed In Linux 7.4 For Nova Lake Laptops](https://www.phoronix.com/news/Linux-7.4-Media)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>Linux 7.4 已合并 media 子系统改动，最引人注目的是为高端 Nova Lake 笔记本的下一代图像处理单元加入 Intel IPU8 支持。</p><blockquote><p><strong>学习价值</strong>：可了解 media 子系统与摄像头/IPU 驱动的上游化节奏，适合关注 V4L2 与图像处理管线的学习者。</p></blockquote><h3 id="kwin-type-introduced-to-address-kde-wayland-usability-gap-for-auto-typing-text" tabindex="-1"><a href="https://www.phoronix.com/news/KDE-KWin-Type" target="_blank" rel="noreferrer">KWin-Type Introduced To Address KDE Wayland Usability Gap For Auto-Typing Text</a> <a class="header-anchor" href="#kwin-type-introduced-to-address-kde-wayland-usability-gap-for-auto-typing-text" aria-label="Permalink to &quot;[KWin-Type Introduced To Address KDE Wayland Usability Gap For Auto-Typing Text](https://www.phoronix.com/news/KDE-KWin-Type)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>WireGuard 作者 Jason Donenfeld 发布了 kwin-type，一个在 KWin Wayland 合成器下从标准输入自动键入文本的 Wayland 兼容程序。该项目旨在弥补 KDE Wayland 在自动输入文本方面的可用性缺口。</p><blockquote><p><strong>学习价值</strong>：虽属用户态项目，但涉及 Wayland 输入协议与合成器权限模型，对理解输入子系统与安全边界有帮助。</p></blockquote><h3 id="linux-7-4-efi-brings-improvement-for-helping-systemd-when-kernel-booted-directly" tabindex="-1"><a href="https://www.phoronix.com/news/Linux-7.4-EFI" target="_blank" rel="noreferrer">Linux 7.4 EFI Brings Improvement For Helping Systemd When Kernel Booted Directly</a> <a class="header-anchor" href="#linux-7-4-efi-brings-improvement-for-helping-systemd-when-kernel-booted-directly" aria-label="Permalink to &quot;[Linux 7.4 EFI Brings Improvement For Helping Systemd When Kernel Booted Directly](https://www.phoronix.com/news/Linux-7.4-EFI)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>Linux 7.4 的 EFI 更新已合入，其中一项改进针对在 EFI 系统上不经 GRUB 或 systemd-boot 而直接引导内核的场景，使 systemd 能更好地获知引导方式。属于 EFI stub / 引导路径相关的核心改动。</p><blockquote><p><strong>学习价值</strong>：适合了解 EFI stub 直接引导流程以及内核如何向用户态（systemd）传递引导来源信息。</p></blockquote><h3 id="nouveau-dkms-aims-for-better-nvidia-open-source-experience-on-old-gpus" tabindex="-1"><a href="https://www.phoronix.com/news/Nouveau-DKMS" target="_blank" rel="noreferrer">Nouveau-DKMS Aims For Better NVIDIA Open-Source Experience On Old GPUs</a> <a class="header-anchor" href="#nouveau-dkms-aims-for-better-nvidia-open-source-experience-on-old-gpus" aria-label="Permalink to &quot;[Nouveau-DKMS Aims For Better NVIDIA Open-Source Experience On Old GPUs](https://www.phoronix.com/news/Nouveau-DKMS)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>Nouveau-DKMS 作为开源 NVIDIA Nouveau 驱动的树外（out-of-tree）分支在开发中，重点改善 GeForce 400/500「Fermi」等 pre-Turing 老 GPU 的支持。背景是 NVIDIA 正在开发面向新硬件的 Nova 驱动，老硬件支持需要另寻出路。</p><blockquote><p><strong>学习价值</strong>：可了解 DKMS 树外模块的维护模式，以及 Nouveau/Nova 驱动在新旧 NVIDIA 硬件上的路线分化。</p></blockquote><h3 id="linux-7-4-begins-employing-new-core-mm-tree" tabindex="-1"><a href="https://www.phoronix.com/news/Linux-Core-MM-Tree" target="_blank" rel="noreferrer">Linux 7.4 Begins Employing New &quot;Core MM&quot; Tree</a> <a class="header-anchor" href="#linux-7-4-begins-employing-new-core-mm-tree" aria-label="Permalink to &quot;[Linux 7.4 Begins Employing New &quot;Core MM&quot; Tree](https://www.phoronix.com/news/Linux-Core-MM-Tree)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>内核维护者同意新建「Core MM」树，作为今后所有核心内存管理改动的统一入口。此前核心 MM 补丁通常经 Andrew Morton 的 MM 分支进入主线，该分支同时承载 DAMON/DAMOS 等更广泛的 MM 相关工作。Linux 7.4 起开始使用这一新树。</p><blockquote><p><strong>学习价值</strong>：对跟踪 mm 子系统补丁流向与维护者流程很有价值，是理解内核开发工作流的好案例。</p></blockquote><h3 id="linux-fixes-amd-ryzen-ai-9-hx-370-regression-due-to-cache-aware-scheduling" tabindex="-1"><a href="https://www.phoronix.com/news/Linux-CAS-Regression-AMD-HX-370" target="_blank" rel="noreferrer">Linux Fixes AMD Ryzen AI 9 HX 370 Regression Due To Cache Aware Scheduling</a> <a class="header-anchor" href="#linux-fixes-amd-ryzen-ai-9-hx-370-regression-due-to-cache-aware-scheduling" aria-label="Permalink to &quot;[Linux Fixes AMD Ryzen AI 9 HX 370 Regression Due To Cache Aware Scheduling](https://www.phoronix.com/news/Linux-CAS-Regression-AMD-HX-370)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>Linux 7.4 合入并标记回迁至 7.2/7.3 stable 的回归修复，解决至少影响 AMD Ryzen AI 9 HX 370「Strix Point」笔记本 SoC 的问题，该问题与 Cache Aware Scheduling 特性相关。属于调度器中 cache-aware 调度路径的缺陷修正。</p><blockquote><p><strong>学习价值</strong>：可用于研究 cache-aware scheduling 在异构/多 CCX 平台上的实现细节与典型回归模式。</p></blockquote>',200)])])}const m=r(n,[["render",l]]);export{h as __pageData,m as default};
